"""Tests for res/fnnames.py: Base4K, the filename cipher, and path-safety helpers.

Vectors:
  * Base4K: the public test vectors from the vendor's README (github.com/secomba/base4k).
  * Filename cipher: frozen regression vectors generated by this implementation under a DISCLOSED key
    (SHA-512 of a public sentence). They are not independent of the implementation: Boxcryptor's servers are
    gone, so no client can produce new reference pairs, and pairs from a real vault cannot be published without
    the key that proves them. What they guarantee is that the cipher does not drift. The 5-byte HMAC embedded in
    every real encrypted name is what validated the implementation against real data.
"""
import hashlib
import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import res.fnnames as F  # noqa: E402

KEY = hashlib.sha512(b"boxcryptor-decryptor test vectors v1").digest()      # 64 bytes: ForEncryption | ForHashing
KEY_HEX = "bf86f4e35dc4ee8108191c270709b7ec495b935a731d1946d9b5d17b029daabd038e9b60385d34426bafbf03cb41ec512180ef3319398f01beb128fda8319375"
UID = "1234567890123456789"

NAME_VECTORS = [
    ("a",
     "倐夸劳傖傊䀌"),
    ("report.docx",
     "倐姟堰嶯婎儛偤嬴儝夽崐劓"),
    ("Vacation photos 2016",
     "倐奠勄哭厒唱妣夃嚤垊儮嶅幄噦兑助廵啰"),
    ("x" * 64,
     "倐変帻协凶坫婴埴哦凅岪哌塭弩刨八巗庬垽寙傔垷夠劋厹壱倩廘埮嬮堸圆嗢唞囫動厝叅叏尣匇墺厹峤嬁弸媞䀌"),
    ("y" * 65,
     "倐妀婚尌哾垥廌埮喋巅働冔博廖呆卅劍帬嵇巬弉傇弣媣兔徸壸嵩埙噕婨廟徕啢岓嬩啾僚堘呜埊媕嚟叻庣夦念廱"),
    ("übergrößé ñ 日本語.txt",
     "倐妇屨咙宆巟壡叾塱对偏喒彖帞岂巑帵哤媩孖僃嶻寢厓䀾"),
    ("archives.bc",
     "倐奕儯則嶵呦嬍嶑匐叜噅崡"),
]


class Base4KTests(unittest.TestCase):

    def test_vendor_readme_vectors(self):
        self.assertEqual(F.base4k_encode(b"f", legacy=False), "䁦")
        self.assertEqual(F.base4k_encode(b"foobar", legacy=False), "晦潯昦慲")
        self.assertEqual(F.base4k_decode("晦潯昦慲"), b"foobar")
        self.assertEqual(F.base4k_decode("䁦"), b"f")

    def test_round_trip_both_alphabets(self):
        for n in range(0, 70):
            data = bytes((i * 37 + 11) & 0xFF for i in range(n))
            self.assertEqual(F.base4k_decode(F.base4k_encode(data, legacy=True)), data, n)
            self.assertEqual(F.base4k_decode(F.base4k_encode(data, legacy=False)), data, n)

    def test_rejects_plain_text(self):
        with self.assertRaises(F.Base4KError):
            F.base4k_decode("hello.txt")


class NameCipherTests(unittest.TestCase):

    def test_key_is_the_disclosed_one(self):
        self.assertEqual(KEY.hex(), KEY_HEX)
        self.assertEqual(F.key_holder_hash(UID), 0x09)

    def test_frozen_vectors_decrypt(self):
        for plain, encrypted in NAME_VECTORS:
            self.assertEqual(F.decrypt_name(encrypted, KEY, UID), plain)

    def test_frozen_vectors_encrypt(self):
        for plain, encrypted in NAME_VECTORS:
            self.assertEqual(F.encrypt_name(plain, KEY, UID), encrypted)

    def test_layout(self):
        raw = F.base4k_decode(NAME_VECTORS[1][1])
        self.assertEqual(raw[0], 1)                                  # tag
        self.assertEqual(raw[1], F.key_holder_hash(UID))             # key holder hash
        self.assertEqual(len(raw), 7 + len(b"report.docx"))          # 5-byte MAC + same-length ciphertext

    def test_wrong_key_or_user_is_rejected(self):
        enc = NAME_VECTORS[1][1]
        with self.assertRaises(F.NameDecryptError):
            F.decrypt_name(enc, os.urandom(64), UID)
        with self.assertRaises(F.NameDecryptError):
            F.decrypt_name(enc, KEY, "999")

    def test_tampering_is_detected(self):
        raw = bytearray(F.base4k_decode(NAME_VECTORS[1][1]))
        raw[-1] ^= 0x01
        with self.assertRaises(F.NameDecryptError):
            F.decrypt_name(F.base4k_encode(bytes(raw)), KEY, UID)

    def test_random_key_round_trip(self):
        key = os.urandom(64)
        for name in ["z", "two words.pdf", "x" * 63, "x" * 64, "x" * 65, "x" * 130]:
            self.assertEqual(F.decrypt_name(F.encrypt_name(name, key, UID), key, UID), name)


class PathSafetyTests(unittest.TestCase):

    def test_safe_component_neutralises_separators_and_dots(self):
        self.assertEqual(F.safe_component("a/b"), "a_b")
        self.assertEqual(F.safe_component("a\\b"), "a_b")
        self.assertEqual(F.safe_component("../etc/passwd"), ".._etc_passwd")
        self.assertEqual(F.safe_component(".."), "_..")
        self.assertEqual(F.safe_component("."), "_.")
        self.assertEqual(F.safe_component(""), "_")
        self.assertEqual(F.safe_component("a\x00b\x1fc"), "a_b_c")
        self.assertEqual(F.safe_component("CON"), "_CON")
        self.assertEqual(F.safe_component("nul.txt"), "_nul.txt")
        self.assertEqual(F.safe_component("Normal name (1).txt"), "Normal name (1).txt")

    def test_decrypted_traversal_attempt_stays_inside(self):
        enc = F.encrypt_name("../../escape.txt", KEY, UID)
        name = F.decrypt_filename(enc + ".bc", KEY, UID)
        self.assertEqual(name, ".._.._escape.txt")
        self.assertTrue(F.is_inside(os.path.join("/dest", name), "/dest"))

    def test_is_inside(self):
        self.assertTrue(F.is_inside("/dest/a/b", "/dest"))
        self.assertTrue(F.is_inside("/dest", "/dest"))
        self.assertFalse(F.is_inside("/dest/../x", "/dest"))
        self.assertFalse(F.is_inside("/destination", "/dest"))

    def test_decrypt_filename_files(self):
        enc = F.encrypt_name("report.docx", KEY, UID)
        self.assertEqual(F.decrypt_filename(enc + ".bc", KEY, UID), "report.docx")
        self.assertEqual(F.decrypt_filename("~$" + enc + ".bc", KEY, UID), "~$report.docx")   # Office lock prefix kept
        self.assertEqual(F.decrypt_filename("plain.txt.bc", KEY, UID), "plain.txt")            # no filename encryption
        self.assertEqual(F.decrypt_filename("archives.bc", KEY, UID), "archives")             # a FILE keeps upstream behaviour

    def test_decrypt_filename_directories(self):
        enc = F.encrypt_name("Photos 2016", KEY, UID)
        self.assertEqual(F.decrypt_filename(enc, KEY, UID, is_directory=True), "Photos 2016")
        self.assertEqual(F.decrypt_filename("archives.bc", KEY, UID, is_directory=True), "archives.bc")   # suffix kept
        self.assertEqual(F.decrypt_filename("archives", KEY, UID, is_directory=True), "archives")
        # a directory encrypted for another key holder stays encrypted (and so distinct from anything else)
        other = F.encrypt_name("Photos 2016", KEY, "42")
        self.assertEqual(F.decrypt_filename(other, KEY, UID, is_directory=True), other)


if __name__ == "__main__":
    unittest.main()
